    { t: 'The limit: the tangent line', n: 'As Δx → 0 the secant slope stops moving and equals the tangent slope. The tangent is defined as this limiting position — not as "the line that touches once".', s: { panel: false, q: 0.02, fan: true } },
    { t: 'Does it match the circle?', n: 'Switch to the circle with Q far from P: the secant is an ordinary chord, clearly crossing the circle twice.', s: { panel: true, q: 2, fan: true } },
    { t: 'Same limit, classical answer', n: 'Let Q slide around to P and the chords rotate into the line perpendicular to the radius at P — exactly the tangent you learned in geometry. The limit definition generalizes it without contradicting it.', s: { panel: true, q: 0.02, fan: true } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    var qi = document.getElementById('qApproachInput');
    qi.value = st.s.q; document.getElementById('qApproachVal').value = st.s.q;
    document.getElementById('panelInput').checked = st.s.panel;
    document.getElementById('showFanInput').checked = st.s.fan;
    S.dx = st.s.q; S.circle = st.s.panel; S.fan = st.s.fan;
    document.getElementById('demoNarration').textContent = st.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + st.t;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

