             tmin: tmin, tmax: tmax };
  }

  function drawLine(layer, P, d, rect, opts) {
    var c = clip(P, d, rect);
    if (!c) return null;
    return layer.line(c.a.x, c.a.y, c.b.x, c.b.y)
      .stroke({ color: PINK, width: opts.width || 2.2,
                opacity: (opts.opacity == null ? 1 : opts.opacity), linecap: 'round' });
  }

  function wedge(layer, grad, P, dT, dS, rect) {
    var cT = clip(P, dT, rect), cS = clip(P, dS, rect);
    var LT = cT ? Math.min(cT.tmax, 430) : 300;
    var LS = cS ? Math.min(cS.tmax, 430) : 300;
    var T = { x: P.x + dT.x * LT, y: P.y + dT.y * LT };
    var Q = { x: P.x + dS.x * LS, y: P.y + dS.y * LS };
    var minx = Math.min(P.x, T.x, Q.x), maxx = Math.max(P.x, T.x, Q.x);
    var miny = Math.min(P.y, T.y, Q.y), maxy = Math.max(P.y, T.y, Q.y);
    var w = (maxx - minx) || 1, h = (maxy - miny) || 1;
    var M = { x: (T.x + Q.x) / 2, y: (T.y + Q.y) / 2 };
    try {
      grad.from((P.x - minx) / w, (P.y - miny) / h).to((M.x - minx) / w, (M.y - miny) / h);
    } catch (e) { /* keep default direction */ }
    return layer.polygon([[P.x, P.y], [T.x, T.y], [Q.x, Q.y]]
      .map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill(grad).stroke('none');
  }

  function rotArc(layer, P, a0, a1, R) {
    var d = a1 - a0;
    while (d > Math.PI) d -= 2 * Math.PI;
    while (d < -Math.PI) d += 2 * Math.PI;
    if (Math.abs(d) < 0.06) return null;
    var x0 = P.x + R * Math.cos(a0), y0 = P.y + R * Math.sin(a0);
    var x1 = P.x + R * Math.cos(a1), y1 = P.y + R * Math.sin(a1);
    var sweep = d > 0 ? 1 : 0, large = Math.abs(d) > Math.PI ? 1 : 0;
    var g = layer.group();
    g.path('M' + x0.toFixed(1) + ',' + y0.toFixed(1) + ' A' + R + ',' + R + ' 0 ' +
           large + ' ' + sweep + ' ' + x1.toFixed(1) + ',' + y1.toFixed(1))
      .fill('none').stroke({ color: GRAY, width: 2.2, linecap: 'round' });
    var tang = a1 + (d > 0 ? Math.PI / 2 : -Math.PI / 2);
    var hx = Math.cos(tang), hy = Math.sin(tang), nx = -hy, ny = hx, s = 11;
    g.polygon([
      [x1 + hx * s * 1.8, y1 + hy * s * 1.8],
      [x1 + nx * s, y1 + ny * s],
      [x1 - nx * s, y1 - ny * s]
    ].map(function (p) { return p[0].toFixed(1) + ',' + p[1].toFixed(1); }).join(' '))
      .fill('#ffffff').stroke({ color: GRAY, width: 2.2, linejoin: 'round' });
    return g;
  }

  function dot(layer, P, r, big) {
    return layer.circle(r * 2).center(P.x, P.y).fill(BLUE)
      .stroke({ color: '#ffffff', width: big ? 2 : 1.2 });
  }

  function info(el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(title, body); });
    return el;
  }

  // ================= panel (a): hump curve =================
  var OX = 48, OY = 512, SC = 60;
  function ax(x) { return OX + x * SC; }
  function ay(y) { return OY - y * SC; }
  function fA(x) { return 4.5 * (1 - Math.exp(-0.47 * x)) - 0.052 * x * x; }
  function dfA(x) { return 2.115 * Math.exp(-0.47 * x) - 0.104 * x; }
  var XMIN = 0.35, XMAX = 7.35;

  (function staticA() {
    bgA.line(OX, OY, 536, OY).stroke({ color: AX, width: 2.2 });
    bgA.polygon('536,504 554,512 536,520').fill(AX);
    bgA.line(OX, OY, OX, 28).stroke({ color: AX, width: 2.2 });
    bgA.polygon('40,28 48,10 56,28').fill(AX);
    halo(bgA.text('x').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX).center(520, 486));
    halo(bgA.text('y').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX).center(74, 28));
    halo(bgA.text('(a)').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX).center(300, 576));

    var pts = [];
    for (var i = 0; i <= 200; i++) {
      var x = XMIN + (XMAX - XMIN) * i / 200;
      pts.push(ax(x).toFixed(1) + ',' + ay(fA(x)).toFixed(1));
    }
    info(curveA.polyline(pts.join(' ')).fill('none')
      .stroke({ color: BLUE, width: 4.5, linecap: 'round', linejoin: 'round' }),
      'A smooth curve y = f(x)',
      'The curve',
      'Any smooth curve will do. The tangent at P is built from the curve itself: pick a second point Q on the curve, draw the line PQ, then let Q slide toward P.');
  })();

  // ================= panel (b): circle =================
  var CX = 940, CY = 385, CR = 140;
  function cpt(t) { return { x: CX + CR * Math.cos(t), y: CY - CR * Math.sin(t) }; }

  (function staticB() {
    info(curveB.circle(2 * CR).center(CX, CY).fill('none').stroke({ color: BLUE, width: 4.5 }),
      'A circle — the classical tangent test case',
      'The circle',
      'For a circle, geometry already defines the tangent: the line through P perpendicular to the radius OP. The limit-of-secants definition must reproduce exactly that line — and it does.');
    halo(bgB.text('(b)').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX).center(CX, 576));
  })();

  // ---------------- render panel (a) ----------------
  function renderA(active) {
    var xp = S.pa;
    var P = { x: ax(xp), y: ay(fA(xp)) };
    var mt = dfA(xp);
    var dT = norm({ x: 1, y: -mt });
    var dxw = Math.min(S.dx, XMAX - xp - 0.02);
    var xq = xp + dxw;
    var Q = { x: ax(xq), y: ay(fA(xq)) };
    var dS = norm({ x: Q.x - P.x, y: Q.y - P.y });

    // shaded wedge between tangent and current secant
    info(wedge(dynA, gradA, P, dT, dS, RA),
      'Angular gap between the secant and the tangent',
      'The shrinking wedge',
      'The shaded wedge measures how far the current secant still is from the tangent direction. As Q slides toward P the wedge narrows to nothing — that vanishing gap IS the limit.');

    // fan of intermediate secants (Q positions between P and the labelled Q)
    var ghostQ = [];
    if (S.fan) {
      [0.60, 0.30, 0.12].forEach(function (f) {
        var gx = xp + dxw * f;
        var G = { x: ax(gx), y: ay(fA(gx)) };
        drawLine(dynA, P, norm({ x: G.x - P.x, y: G.y - P.y }), RA, { width: 2, opacity: 0.6 });
        ghostQ.push(G);
      });
    }

    // rotation arc: from the shallow secant up to the tangent
    var aS = Math.atan2(dS.y, dS.x), aT = Math.atan2(dT.y, dT.x);
    var arc = rotArc(dynA, P, aS, aT, 268);
    if (arc) info(arc, 'Direction the secants rotate as Q → P',
      'Rotation toward the limit',
      'Every secant pivots about P. The gray arrow shows the single direction they rotate in: monotonically toward one limiting line rather than wandering.');

    // tangent + current secant
    info(drawLine(dynA, P, dT, RA, { width: 3 }),
      'Tangent line at P (slope ' + mt.toFixed(3) + ')',
      'Tangent line',
      'The tangent is defined as the limiting position of the secants — not as "a line touching the curve once". Its slope is the derivative f\u2032 at P.');
    info(drawLine(dynA, P, dS, RA, { width: 2.6 }),
      'Secant line through P and Q (slope ' + ((fA(xq) - fA(xp)) / dxw).toFixed(3) + ')',
      'Secant line',
      'A secant cuts the curve at two points, P and Q. Its slope is the average rate of change Δy/Δx between them.');

    // rise / run triangle
    if (Q.x - P.x > 46) {
      dynA.polyline([[P.x, P.y], [Q.x, P.y], [Q.x, Q.y]].map(function (p) { return p.join(','); }).join(' '))
        .fill('none').stroke({ color: '#7a7a7a', width: 1.4, dasharray: '5,4' });
      halo(fgA.text('Δx').font({ family: SANS, size: 17 }).fill('#5c5c5c')
        .center((P.x + Q.x) / 2, P.y + 15));
      halo(fgA.text('Δy').font({ family: SANS, size: 17 }).fill('#5c5c5c')
        .center(Q.x + 19, (P.y + Q.y) / 2));
    }

    // points
    ghostQ.forEach(function (G) { dot(fgA, G, 6); });
    var qd = dot(fgA, Q, 7.5, true).css('cursor', 'ew-resize');
    info(qd, 'Q — drag left to slide it toward P', 'The moving point Q',
      'Q is the second point. Sliding it toward P makes the secant swing; the whole construction is about what happens in the limit Q → P.');
    var pd = dot(fgA, P, 8.5, true).css('cursor', 'grab');
    info(pd, 'P — drag along the curve', 'The fixed point P',
      'P stays pinned while Q slides in. Drag P: the tangent direction changes from point to point, and it is exactly horizontal (slope 0) at the crest of the hump.');
    if (active) { dragP_A(pd); dragQ_A(qd); }

    halo(fgA.text('P').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX)
      .center(P.x - 24, P.y - 17));
    halo(fgA.text('Q').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX)
      .center(Q.x + 10, Q.y + 25));

    // annotation labels with leaders
    var tl = { x: P.x + dT.x * 205, y: P.y + dT.y * 205 };
    fgA.line(214, 176, tl.x, tl.y).stroke({ color: '#8d8d8d', width: 1.1 });
    halo(fgA.text('Tangent\nline').font({ family: SANS, size: 23, leading: 1.15 }).fill(AX).move(96, 126));
    var cS = clip(P, dS, RA);
    var Ls = cS ? Math.min(cS.tmax * 0.92, 330) : 300;
    var sl = { x: P.x + dS.x * Ls, y: P.y + dS.y * Ls };
    fgA.line(462, 350, sl.x, sl.y).stroke({ color: '#8d8d8d', width: 1.1 });
    halo(fgA.text('Secant\nline').font({ family: SANS, size: 23, leading: 1.15 }).fill(AX).move(466, 330));

    return {
      px: xp, py: fA(xp), qx: xq, qy: fA(xq),
      ms: (fA(xq) - fA(xp)) / dxw, mt: mt, gap: dxw, unit: ''
    };
  }

  // ---------------- render panel (b) ----------------
  function renderB(active) {
    var tp = S.pb, P = cpt(tp);
    var u = { x: -Math.sin(tp), y: -Math.cos(tp) };
    var dT = (u.y < 0) ? u : { x: -u.x, y: -u.y };
    var step = 21.5 * Math.PI / 180;
    var dth = S.dx * step;
    var tq = tp - dth, Q = cpt(tq);
    var dS = norm({ x: Q.x - P.x, y: Q.y - P.y });

    info(wedge(dynB, gradB, P, dT, dS, RB),
      'Angular gap between chord and tangent',
      'The shrinking wedge',
      'Exactly as on the hump, the wedge between the chord PQ and the tangent closes up as Q swings around to P.');

    if (S.fan) {
      [0.60, 0.30, 0.12].forEach(function (f) {
        var G = cpt(tp - dth * f);
        drawLine(dynB, P, norm({ x: G.x - P.x, y: G.y - P.y }), RB, { width: 2, opacity: 0.6 });
        dot(fgB, G, 6);
      });
    }

    var aS = Math.atan2(dS.y, dS.x), aT = Math.atan2(dT.y, dT.x);
    var arc = rotArc(dynB, P, aS, aT, 232);
    if (arc) info(arc, 'Chords rotate into the tangent', 'Rotation toward the limit',
      'The chords sweep steadily upward until they land on the line perpendicular to the radius at P.');

    info(drawLine(dynB, P, dT, RB, { width: 3 }),
      'Tangent line at P (⊥ to the radius)', 'Tangent line',
      'This is the limiting line of the chords — and it is precisely the line perpendicular to the radius OP, the tangent you met in geometry.');
    info(drawLine(dynB, P, dS, RB, { width: 2.6 }),
      'Secant (chord) through P and Q', 'Secant line',
      'On a circle the secant is an ordinary chord: it clearly crosses the circle twice, so "touches once" cannot be the definition being used.');

    var qd = dot(fgB, Q, 7.5, true).css('cursor', 'grab');
    info(qd, 'Q — drag around the rim toward P', 'The moving point Q',
      'Slide Q around the circle toward P and watch the chord straighten into the tangent.');
    var pd = dot(fgB, P, 8.5, true).css('cursor', 'grab');
    info(pd, 'P — drag around the circle', 'The fixed point P',
      'Wherever P sits on the circle, the limiting line is perpendicular to the radius there. The limit definition agrees with classical geometry at every point.');
    if (active) { dragP_B(pd); dragQ_B(qd); }

    halo(fgB.text('P').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX)
      .center(P.x - 26, P.y - 6));
    halo(fgB.text('Q').font({ family: SERIF, size: 24, style: 'italic' }).fill(AX)
      .center(Q.x + 8, Q.y + 26));

    var tl = { x: P.x + dT.x * 150, y: P.y + dT.y * 150 };
    fgB.line(792, 98, tl.x, tl.y).stroke({ color: '#8d8d8d', width: 1.1 });
    halo(fgB.text('Tangent\nline').font({ family: SANS, size: 23, leading: 1.15 }).fill(AX).move(672, 46));
    var cS = clip(P, dS, RB);
    var Ls = cS ? Math.min(cS.tmax * 0.9, 300) : 280;
    var sl = { x: P.x + dS.x * Ls, y: P.y + dS.y * Ls };
    fgB.line(1124, 264, sl.x, sl.y).stroke({ color: '#8d8d8d', width: 1.1 });
    halo(fgB.text('Secant\nline').font({ family: SANS, size: 23, leading: 1.15 }).fill(AX).move(1126, 246));

    var ms = -(Q.y - P.y) / ((Q.x - P.x) || 1e-9);
    var mt = -dT.y / (dT.x || 1e-9);
    return {
      px: (P.x - CX) / CR, py: (CY - P.y) / CR,
      qx: (Q.x - CX) / CR, qy: (CY - Q.y) / CR,
      ms: ms, mt: mt, gap: Math.hypot(Q.x - P.x, Q.y - P.y) / CR, unit: ' r'
    };
  }

  // ---------------- dragging ----------------
  function svgPt(evt) {
    var r = draw.node.getBoundingClientRect();
    return { x: (evt.clientX - r.left) / r.width * W, y: (evt.clientY - r.top) / r.height * H };
  }
  function makeDrag(el, move) {
    el.on('mousedown', function (e) {
      e.preventDefault();
      function mv(ev) { move(svgPt(ev)); render(); }
      function up() {
        window.removeEventListener('mousemove', mv);
        window.removeEventListener('mouseup', up);
      }
      window.addEventListener('mousemove', mv);
      window.addEventListener('mouseup', up);
    });
  }
  function setSlider(v) {
    S.dx = v;
    var i = document.getElementById('qApproachInput');
    var o = document.getElementById('qApproachVal');
    if (i) i.value = v;
    if (o) o.value = v.toFixed(2);
  }
  function dragP_A(el) {
    makeDrag(el, function (p) {
      var x = (p.x - OX) / SC;
      S.pa = Math.max(0.55, Math.min(5.6, x));
    });
  }
  function dragQ_A(el) {
    makeDrag(el, function (p) {
      var x = (p.x - OX) / SC;
      setSlider(Math.max(0.05, Math.min(4, x - S.pa)));
    });
  }
  function dragP_B(el) {
    makeDrag(el, function (p) { S.pb = Math.atan2(CY - p.y, p.x - CX); });
  }
  function dragQ_B(el) {
    makeDrag(el, function (p) {
      var t = Math.atan2(CY - p.y, p.x - CX);
      var d = S.pb - t;
      while (d < 0) d += 2 * Math.PI;
      while (d > 2 * Math.PI) d -= 2 * Math.PI;
      var v = d / (21.5 * Math.PI / 180);
      setSlider(Math.max(0.05, Math.min(4, v)));
    });
  }

  // ---------------- master render ----------------
  var readout = document.getElementById('readout');
  function render() {
    dynA.clear(); dynB.clear(); fgA.clear(); fgB.clear(); focusL.clear();
    var r = S.circle ? RB : RA;
    focusL.rect(r.x1 - r.x0 + 20, r.y1 - r.y0 + 44)
      .move(r.x0 - 10, r.y0 - 10).radius(10).fill('#f2f8fc').stroke('none');

    var ia = renderA(!S.circle);
    var ib = renderB(S.circle);
    var d = S.circle ? ib : ia;
    var f = function (v) { return (Math.abs(v) < 5e-4 ? 0 : v).toFixed(3); };
    var conv = Math.abs(d.ms - d.mt) < 0.02;
    readout.innerHTML =
      '<b>Panel ' + (S.circle ? '(b) circle' : '(a) curve') + '</b><br>' +
      'P = (' + f(d.px) + ', ' + f(d.py) + ')<br>' +
      'Q = (' + f(d.qx) + ', ' + f(d.qy) + ')<br>' +
      'secant slope Δy/Δx = <b>' + f(d.ms) + '</b><br>' +
      'tangent slope&nbsp;&nbsp;&nbsp;&nbsp; = <b style="color:' + PINK + '">' + f(d.mt) + '</b><br>' +
      'gap |Q − P| = ' + f(d.gap) + d.unit +
      (conv ? '<br><span style="color:#1a7f37">secant ≈ tangent — the limit</span>' : '');
  }

  // ---------------- controls ----------------
  window.update_qApproach = function (v) { S.dx = v; render(); };
  window.toggle_panel = function (on) { S.circle = on; render(); };
  window.toggle_showFan = function (on) { S.fan = on; render(); };

  // ---------------- demo steps ----------------
  var steps = [
    { t: 'A secant through two points',
      n: 'P is pinned on the curve and Q sits far away. The pink lines through P are secants — each cuts the curve at two points, and its slope is just the rise Δy over the run Δx.',
      s: { panel: false, q: 3.9, fan: true } },
    { t: 'Slide Q toward P',
      n: 'Drag Q closer (or use the slider). The secant pivots about P and the slope readout shifts — each new Q gives a different, but progressively less different, line.',
      s: { panel: false, q: 1.4, fan: true } },
    { t: 'The fan closes on one line',
      n: 'With the trail of secants shown, the rotation is unmistakable: the lines fan out from P and crowd toward a single direction. The shaded wedge between secant and tangent is nearly gone.',
      s: { panel: false, q: 0.45, fan: true } },
    { t: 'The limit: the tangent line',
      n: 'As Δ → 0 the secant slope stops moving and equals the tangent slope. The tangent IS this limiting position — not "the line that touches once".',
      s: { panel: false, q: 0.05, fan: true } },
    { t: 'Does it match the circle?',
      n: 'Switch focus to the circle with Q far from P: the secant is an ordinary chord, clearly crossing the circle twice.',
      s: { panel: true, q: 3.9, fan: true } },
    { t: 'Same limit, classical answer',
      n: 'Let Q slide around to P and the chords rotate into the line perpendicular to the radius at P — exactly the tangent from geometry. The limit definition generalizes it without contradicting it.',
      s: { panel: true, q: 0.05, fan: true } }
  ];
  var cur = 0;
  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    setSlider(st.s.q);
    S.circle = st.s.panel;
    S.fan = st.s.fan;
    document.getElementById('panelInput').checked = st.s.panel;
    document.getElementById('showFanInput').checked = st.s.fan;
    document.getElementById('demoNarration').textContent = st.n;
    document.getElementById('stepLabel').textContent = (cur + 1) + '/' + steps.length + ' · ' + st.t;
    render();
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  applyStep(0);
  window.__markRendered();
})();
// @FIGURE_CODE_END

